async def act(page):
    import asyncio
    import re

    # Knowledge-base function utility reasoning:
    # - export_customers_csv_via_grid exists in the KB, but it exports the Customers management CSV.
    #   That CSV does not include per-order statuses needed to count cancelled orders by customer.
    #   Therefore it is not useful for this task and will not be called.

    # Give the UI a short moment to stabilize from the current state
    await asyncio.sleep(0.25)

    # 1) Locate the Status filter combobox by finding a combobox that contains an option named "Canceled"
    status_comboboxes = page.get_by_role("combobox").filter(
        has=page.get_by_role("option", name="Canceled")
    )
    if await status_comboboxes.count() == 0:
        # Status combobox not found -> nothing to count
        print("0")
        return
    status_cb = status_comboboxes.nth(0)

    # 2) Select the "Canceled" option (best-effort)
    try:
        await status_cb.select_option(label="Canceled")
    except Exception:
        # non-fatal; proceed even if selection fails (might already be selected)
        pass

    # 3) Click the Search button scoped to the "Reset Filter Search" cell (full path)
    search_btn = None
    reset_cell = page.get_by_role("cell", name="Reset Filter Search")
    if await reset_cell.count() > 0:
        try:
            btns = reset_cell.get_by_role("button", name="Search")
            if await btns.count() > 0:
                search_btn = btns.nth(0)
        except Exception:
            search_btn = None
    if search_btn is None:
        # fallback to any page-level Search button
        pbtns = page.get_by_role("button", name="Search")
        if await pbtns.count() > 0:
            search_btn = pbtns.nth(0)

    if search_btn is not None:
        await search_btn.click()
        await asyncio.sleep(0.6)  # wait for grid to refresh

    # 4) Determine total number of pages from the pager cell that contains the "Go to Next page" link
    pager_cells = page.get_by_role("cell").filter(
        has=page.get_by_role("link", name="Go to Next page")
    )
    total_pages = 1
    if await pager_cells.count() > 0:
        pager = pager_cells.nth(0)
        try:
            txt = await pager.inner_text()
            m = re.search(r"of\s+(\d+)\s+pages", txt, re.IGNORECASE)
            if not m:
                m = re.search(r"of\s+(\d+)", txt, re.IGNORECASE)
            if m:
                total_pages = int(m.group(1))
        except Exception:
            total_pages = 1

    # 5) Helper to locate the orders table (the table that contains a cell named "Order #")
    async def find_orders_table():
        tables = page.get_by_role("table")
        tcount = await tables.count()
        for ti in range(tcount):
            t = tables.nth(ti)
            try:
                if await t.get_by_role("cell", name="Order #").count() > 0:
                    return t
            except Exception:
                continue
        return None

    # 6) Determine header indices for Bill to Name and Status
    orders_table = await find_orders_table()
    if orders_table is None:
        print("0")
        return

    rows = orders_table.get_by_role("row")
    rcount = await rows.count()
    header_row = None
    for ri in range(rcount):
        r = rows.nth(ri)
        try:
            if await r.get_by_role("cell", name="Order #").count() > 0:
                header_row = r
                break
        except Exception:
            continue
    if header_row is None:
        header_row = rows.nth(0)

    header_cells = header_row.get_by_role("cell")
    hc = await header_cells.count()
    bill_idx = None
    status_idx = None
    for ci in range(hc):
        try:
            htxt = (await header_cells.nth(ci).inner_text() or "").strip().lower()
        except Exception:
            htxt = ""
        if "bill to name" in htxt or ("bill" in htxt and "name" in htxt):
            bill_idx = ci
        if "status" in htxt:
            status_idx = ci
    # sensible fallbacks
    if bill_idx is None:
        bill_idx = 4 if hc > 4 else 0
    if status_idx is None:
        status_idx = max(0, hc - 2)

    # 7) Iterate through each page and tally cancelled orders per customer
    cancels_by_customer = {}
    for page_num in range(1, total_pages + 1):
        # Re-resolve orders_table each page to avoid stale locators
        orders_table = await find_orders_table()
        if orders_table is None:
            break

        rows = orders_table.get_by_role("row")
        rcount = await rows.count()
        for ri in range(rcount):
            row = rows.nth(ri)
            try:
                if await row.get_by_role("link", name="View").count() == 0:
                    continue
            except Exception:
                continue

            cells = row.get_by_role("cell")
            ccount = await cells.count()
            try:
                status_text = (await cells.nth(status_idx).inner_text()).strip().lower() if status_idx < ccount else ""
            except Exception:
                status_text = ""
            if "cancel" not in status_text:
                continue
            try:
                cust = (await cells.nth(bill_idx).inner_text()).strip() if bill_idx < ccount else ""
            except Exception:
                cust = ""
            if not cust:
                cust = "<unknown>"
            cancels_by_customer[cust] = cancels_by_customer.get(cust, 0) + 1

        # If more pages remain, click the "Go to Next page" link and wait
        if page_num < total_pages:
            pager_cells = page.get_by_role("cell").filter(
                has=page.get_by_role("link", name="Go to Next page")
            )
            if await pager_cells.count() == 0:
                break
            pager = pager_cells.nth(0)
            try:
                next_links = pager.get_by_role("link", name="Go to Next page")
                if await next_links.count() > 0:
                    await next_links.nth(0).click()
                    await asyncio.sleep(0.6)
                else:
                    break
            except Exception:
                break

    # 8) Compute maximum cancellations and print only the numeric result
    max_cancels = max(cancels_by_customer.values()) if cancels_by_customer else 0
    print(str(max_cancels))
